{
  "name": "OBF实验数据文件",
  "name_en": "OBF Experimental Data File",
  "manufacturer": "",
  "description": "一种用于保存实验数据堆栈及其元数据的 OBF 文件，常见于显微成像等实验数据的存储、归档与离线分析。文件中可包含多个数据堆栈，并记录头信息、描述信息及相关单位信息。",
  "description_en": "An OBF file used to store experimental data stacks and their metadata, commonly for microscopy and similar laboratory imaging workflows. It can contain multiple data stacks along with header information, descriptions, and unit-related metadata for storage, archiving, and offline analysis.",
  "tag_hints": [
    "OBF file format",
    "image stacks",
    "microscopy data",
    "experimental metadata",
    "offline data analysis"
  ],
  "actions": [
    {
      "action_name": "auto-find_stack_by_name",
      "description": "按名称片段查找 OBF 文件中的数据堆栈。",
      "description_en": "Find data stacks in the OBF file by partial name."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 OBF 文件。",
      "description_en": "Close the OBF file."
    }
  ]
}

